const mechanismsByName = new Map();
for (const rule of [...bulkIntegrationModes, ...reviewedIntegrationModes, ...mechanicModes]) {
  for (const name of rule.names) if (!mechanismsByName.has(name)) mechanismsByName.set(name, rule);
}
export function talentMechanism(name) {
  const rule = mechanismsByName.get(normalize(name).replace(/[^a-z]/g, ''));
  return rule ? {mode:rule.mode, label:rule.label, detail:rule.detail} : {mode:'unreviewed',
    label:'Mécanisme non examiné', detail:'Ce talent ne fait pas encore partie des talents implémentés à partir de la revue.'};
}
function includeInSummary(actor, talent) {
  return !actor.items.get(talent.itemId)?.flags?.starwarsffg?.characteristicIncrease?.creationTool &&
    !['augmenter un attribut', 'increase a characteristic'].includes(normalize(talent.name));
}
export function hasSummaryTalents(actor) {
  return (actor.talentList ?? []).some(talent => includeInSummary(actor, talent));
}
export function summaryTalents(actor) {
  return (actor.talentList ?? []).filter(talent => includeInSummary(actor, talent)).map(talent => {
    const activation = normalize(talent.activation || talent.activationLabel);
    const active = activation.includes('active') || activation.includes('actif') || activation.includes('declenche');
    const rank = Number(talent.rank);
    let total = '';
    // Only unconditional, known per-rank bonuses can be summarized this way.
    if (talent.isRanked && Number.isFinite(rank) && rank > 0) {
      const name = normalize(talent.name);
      if (['endurci', 'toughened'].includes(name)) total = game.i18n.format("SWFFG.UI.Talent.TotalWoundsBonus", {rank});
      if (['robustesse', 'robuste', 'grit'].includes(name)) total = game.i18n.format("SWFFG.UI.Talent.TotalStrainBonus", {rank});
    }
    return {...talent, active, total, mechanism:talentMechanism(talent.name)};
  }).sort((a, b) => Number(b.active) - Number(a.active) || a.name.localeCompare(b.name, game.i18n.lang));
}

function acquisitionSources(talent) {
  return talent.source?.length ? talent.source : [{id:talent.itemId}];
}

export async function talentDescription(actor, talent) {
  const owned = actor.items.get(talent.itemId);
  const choices = talentChoiceKind(talent.name) ? acquisitionSources(talent)
    .map(source => talentChoiceDescription(actor, source.id, source.slot ?? '_self')).join('') : '';
  const text = talent.description || owned?.system.description || game.i18n.localize("SWFFG.UI.Talent.NoSummaryDescription");
  const description = document.createElement('div');
  description.innerHTML = await foundry.applications.ux.TextEditor.enrichHTML(normalizeBoldTags(text + choices), {secrets: actor.isOwner, relativeTo: actor});
  description.querySelectorAll('.ffg-talent-source, .ffg-talent-review-status').forEach(node => node.remove());
  description.querySelectorAll('p').forEach(node => node.style.textAlign = 'justify');
  return description;
}

export async function showTalentSummary(sheet, refresh = false, anchor = sheet.element) {
  if (refresh && !sheet._talentSummary?.rendered) return;
  if (!refresh && sheet._talentSummary?.rendered) {
    sheet._talentSummary.bringToFront();
    return;
  }
  return renderSummary(sheet,'_talentSummary',refresh,async current=>{
  const actor = sheet.actor;
  const expandedPassives = new Set(refresh ? Array.from(sheet._talentSummary?.element?.querySelectorAll('details.ffg-passive-talent[open]') ?? [], node => node.dataset.talentKey) : []);
  const content = document.createElement('div');
  const body = append(content, 'div');
  body.className = 'ffg-talent-summary-body';
  body.style.cssText = 'max-height:min(360px,42vh);overflow:auto;font-size:12px;line-height:1.4;padding-right:6px';
  const talents = summaryTalents(actor);
  if (!talents.length) append(body, 'p', game.i18n.localize("SWFFG.UI.Talent.NoneAcquired"));
  for (const talent of talents) {
    if(!current())return;
    const section = append(body, talent.active ? 'section' : 'details');
    if (!talent.active) {
      section.className = 'ffg-passive-talent';
      section.dataset.talentKey = `${talent.itemId}:${talent.name}:${talent.characteristicChoice ?? ''}`;
      section.open = expandedPassives.has(section.dataset.talentKey);
    }
    section.style.cssText = 'padding:8px;border-bottom:1px solid #8886;' + (talent.active ? 'background:var(--ffg-accent-surface,#dce5e9);border-left:3px solid #687f8b;margin-bottom:5px;border-radius:3px' : '');
    const rank = talent.isRanked ? ' - '+game.i18n.format("SWFFG.UI.Talent.RankNumber", {rank:talent.rank}) : '';
    const choice = talent.characteristicChoice ? ` - ${talent.characteristicChoice}` : '';
    const heading = talent.active ? section : append(section, 'summary');
    const title = append(heading, 'h3', `${talent.name}${choice}`);
    title.style.cssText = `font-size:14px;margin:0 0 4px;color:${talent.active ? 'var(--ffg-link,#354f5d)' : 'var(--ffg-ink,#582323)'}`;
    if (rank) append(title, 'span', rank).className = 'ffg-talent-summary-rank';
    append(section, 'p', talent.active ? game.i18n.localize("SWFFG.UI.Talent.Active") : game.i18n.localize("SWFFG.UI.Talent.Passive")).style.cssText = 'margin:0 0 5px;opacity:.8';
    if (talent.total) append(section, 'p', talent.total).style.cssText = 'margin:0 0 5px;font-weight:bold';
    section.append(await talentDescription(actor, talent));
  }
  if(!current())return;
  if (refresh) {
    await sheet._talentSummary.setContent(content);
    return;
  }
  const width = Math.min(360, window.innerWidth - 24);
  const bounds = anchor.getBoundingClientRect();
  const right = bounds.right + 8;
  const left = right + width <= window.innerWidth ? right : Math.max(0, bounds.left - width - 8);
  sheet._talentSummary = summaryDialog({
    classes: ['starwarsffg', 'themed'],
    window: {title: game.i18n.localize('SWFFG.TabTalents')+' - '+actor.name, resizable:true},
    position: {width, left, top: Math.max(0, Math.min(bounds.top, window.innerHeight - 200))},
    content,
    buttons: [{action:'close', label:game.i18n.localize('SWFFG.ButtonClose')}]
  });
  await sheet._talentSummary.render({force:true});
  });
}

/** Visible next to each talent; text-only DOM additions never alter descriptions. */
export function annotateTalentMechanisms(sheet){
 const root=sheet.element;if(!root)return;
 root.querySelectorAll('.ffg-direct-talent-choice, .ffg-talent-choice-status').forEach(e=>e.remove());
 for (const row of root.querySelectorAll('.specialization-talent-item[data-item-name]')) {
  if (!talentChoiceKind(row.dataset.itemName)) continue;
  const talent = sheet.actor?.talentList?.[row.dataset.talentIndex];
  const sources = talent ? acquisitionSources(talent) : [{id:row.dataset.itemId}];
  for (const source of sources) appendDirectChoice(row.querySelector('.item-controls'), row.dataset.itemName, source.id, source.slot ?? '_self');
 }
 for(const title of root.querySelectorAll('.specialization-talent .talent-name[data-name]')){
  if(talentChoiceKind(title.dataset.name) === 'dedication')continue;
  const body=title.closest('.talent-background')?.querySelector('.talent-body');appendDirectChoice(body,title.dataset.name,sheet.item?.id,title.closest('.specialization-talent')?.id);
 }
 function appendDirectChoice(parent,name,itemId,slot=null){
  if(!parent||!talentChoiceKind(name))return;
  const actor=sheet.actor??(sheet.item?.parent?.documentName==='Actor'?sheet.item.parent:null);
  if(!actor?.isOwner){if(sheet.item?.type==='talent'){const help=document.createElement('p');help.className='ffg-direct-talent-choice';help.textContent=game.i18n.format("SWFFG.UI.Talent.AddToActorHelp", {name});parent.append(help);}return;}
  const item=actor.items.get(itemId),nodes=item?.type==='talent'?[['_self',{islearned:true,name:item.name}]]:Object.entries(item?.system?.talents??{});
  const source=nodes.find(([key,node])=>node.islearned===true&&(!slot||key===slot)&&normalize(node.name)===normalize(name));
  if(!source)return;
  const choice=item.flags?.starwarsffg?.reviewedTalentChoices?.[source[0]];
  const el=document.createElement('button');el.className='item-control ffg-direct-talent-choice';
  el.type='button';el.style.cssText='display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;width:22px;height:22px;min-height:0;margin:0;padding:0;border:0;background:none;box-shadow:none;color:inherit';
  const chosen=(choice?.skills??[]).map(k=>game.i18n.localize(actor.system.skills[k]?.label??k)).join(', ');
  el.title=game.i18n.format("SWFFG.UI.Talent.ConfigureTalent", {name})+(chosen?' : '+chosen:'');el.setAttribute('aria-label',el.title);
  const icon=document.createElement('i');icon.className='fas fa-gear';icon.setAttribute('aria-hidden','true');el.append(icon);
  el.addEventListener('click',async e=>{e.preventDefault();e.stopPropagation();el.disabled=true;try{const {configureSpecificTalent}=await import('./reviewed-talent-ui.js');await configureSpecificTalent(actor,item.id,source[0]);}catch(error){ui.notifications.error(error.message);}finally{el.disabled=false;}});
  parent.prepend(el);
  const status=talentChoiceStatus(actor,item.id,source[0])[0];
  if(status){const note=document.createElement('small');note.className='ffg-talent-choice-status';note.textContent=status.text;note.style.cssText='display:block;white-space:normal;margin-top:4px;line-height:1.3;font-style:italic;font-weight:400;flex:0 0 auto';
   if(!status.skills.length){const emptyText=status.emptyLabel??game.i18n.localize('SWFFG.UI.Talent.ChoiceNone');const at=status.text.indexOf(emptyText);note.textContent=status.text.slice(0,at);const empty=document.createElement('strong');empty.className='ffg-talent-choice-empty';empty.textContent=emptyText;note.append(empty,document.createTextNode(status.text.slice(at+emptyText.length)));}
   const target=parent.closest('.specialization-talent-item')?.querySelector('.item-name')??parent;
   if(target.classList.contains('item-name'))target.classList.add('ffg-talent-with-choice');
   target.append(note);
  }
 }
 if(sheet.item?.type==='talent'){const header=root.querySelector('.sheet-header');const host=document.createElement('div');host.className='ffg-direct-talent-choice';header?.after(host);appendDirectChoice(host,sheet.item.name,sheet.item.id);}

}
